<?php require_once "../db.php";require_role("Teacher");$qid=(int)($_GET["quiz_id"]??$_POST["quiz_id"]??0);$uid=current_id();$q=$conn->prepare("SELECT * FROM quiz WHERE id=? AND created_by=?");$q->bind_param("ii",$qid,$uid);$q->execute();if(!$q->get_result()->fetch_assoc())die("Quiz not found.");if($_SERVER["REQUEST_METHOD"]==="POST"){$question=trim($_POST["question"]);$a=$_POST["a"];$b=$_POST["b"];$c=$_POST["c"];$d=$_POST["d"];$correct=$_POST["correct"];$st=$conn->prepare("INSERT INTO questions(quiz_id,question,option_a,option_b,option_c,option_d,correct_answer) VALUES(?,?,?,?,?,?,?)");$st->bind_param("issssss",$qid,$question,$a,$b,$c,$d,$correct);$st->execute();$conn->query("UPDATE quiz SET total_questions=(SELECT COUNT(*) FROM questions WHERE quiz_id=$qid) WHERE id=$qid");go("manage_questions.php?quiz_id=".$qid);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add Question</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card panel-card"><div class="card-body p-5"><h2 class="fw-bold">Add Question</h2><form method="post"><input type="hidden" name="quiz_id" value="<?=$qid?>"><label class="form-label">Question</label><textarea name="question" class="form-control mb-3" required></textarea><div class="row g-3"><?php foreach(["a","b","c","d"] as $x):?><div class="col-md-6"><label class="form-label">Option <?=strtoupper($x)?></label><input name="<?=$x?>" class="form-control" required></div><?php endforeach;?></div><label class="form-label mt-3">Correct Answer</label><select name="correct" class="form-select mb-3"><option value="A">A</option><option value="B">B</option><option value="C">C</option><option value="D">D</option></select><button class="btn btn-primary">Save Question</button></form></div></div></div></body></html>
